import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.effect.*;
import dev.hua.ptcglive.engine.field.*;
import dev.hua.ptcglive.rules.*;
import java.util.*;

public final class StarterDeck100WishiwashiTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    static final String WATER="sd100_cn_water_energy";
    static CardInstance attach(ServerMatch m,String card){return StarterDeck100EnergyTest.attach(m,A,A,card,m.activePokemonView(A).pokemonId());}
    public static void main(String[] args){threshold();damage();lostEnergy();suppression();cycles();System.out.println("StarterDeck100WishiwashiTest passed: actual Water units, Rapid Strike double provision, Basic-only attack scaling, immediate HP-loss KOs, suppression and pre-setup cycle rejection");}
    static void threshold(){var m=StarterDeck100PokemonTest.game(113,1,WATER,id(414));check(m.activePokemonView(A).hitPoints()==30,"printed HP");attach(m,id(414));check(m.activePokemonView(A).hitPoints()==30,"two Water units incorrectly met three-unit threshold");var water=attach(m,WATER);check(m.activePokemonView(A).hitPoints()==180,"Rapid Strike plus Basic Water must be180HP");var before=m.clientView(A);var rng=m.randomTranscript();for(int i=0;i<5;i++)m.clientView(B);check(before.equals(m.clientView(A))&&rng.equals(m.randomTranscript()),"HP query mutated state");m.returnAttachedEnergyToHandByEffect(A,A,m.activePokemonView(A).pokemonId(),List.of(water.instanceId()));check(m.activePokemonView(A).hitPoints()==30,"lost Water retained HP bonus");}
    static void damage(){var m=StarterDeck100PokemonTest.game(113,1,WATER,id(414));attach(m,id(414));attach(m,WATER);attach(m,"sd100_cn_grass_energy");m.attack(A,"schooling-shot");check(m.lastAttack().finalDamage()==90,"Schooling Shot must count Basic Water AND Grass, exclude Special Energy units");}
    static void lostEnergy(){var m=StarterDeck100PokemonTest.game(113,1,WATER,id(414));attach(m,id(414));var water=attach(m,WATER);var host=m.activePokemonView(A).pokemonId();m.placeDamageCountersByEffect(A,A,host,10);check(m.phase()==MatchPhase.TURN,"damage below boosted HP caused premature KO");m.moveAttachedEnergyByEffect(A,A,host,A,m.benchPokemonView(A).getFirst().pokemonId(),List.of(water.instanceId()));check(m.phase()==MatchPhase.PRIZE_SELECTION,"HP drop from Energy movement did not KO");StarterDeck100CombatTest.settleKnockouts(m);check(m.publicView().get(B).prizeCount()==5&&!m.activePokemonView(A).pokemonId().equals(host),"HP-loss KO wrong prize or replacement");}
    static void suppression(){var m=StarterDeck100PokemonTest.game(113,100,WATER);for(int i=0;i<3;i++)attach(m,WATER);check(m.activePokemonView(A).hitPoints()==30,"Emperor Eyes failed to suppress Group Power");var ordinary=StarterDeck100PokemonTest.game(113,1,WATER);for(int i=0;i<3;i++)attach(ordinary,WATER);check(ordinary.activePokemonView(A).hitPoints()==180,"three Basic Waters did not boost HP");var host=ordinary.activePokemonView(A).pokemonId();ordinary.placeDamageCountersByEffect(A,A,host,10);ordinary.disableAbilityEffectsByEffect(A,A,host);check(ordinary.phase()==MatchPhase.PRIZE_SELECTION,"suppression HP loss did not KO immediately");}
    static void cycles(){var base=StarterDeck100CombatTest.COMBAT;var energy=new EnergyProfile(EnergyProfile.basic(EnergyType.WATER).units(),EffectProgram.EMPTY,List.of(new EnergyProvisionRule(List.of(new ConditionDefinition(ConditionType.HP_ABOVE,Map.of("value","10"),List.of())),EnergyProfile.fixed(EnergyType.WATER,3).units())));var profiles=new LinkedHashMap<>(base.energyProfiles());profiles.put("hp-energy",energy);var combat=new CombatCatalog(base.pokemonProfiles(),Map.of(),base.trainerProfiles(),profiles);var cards=new ArrayList<>(StarterDeck100CombatTest.CARDS.all());cards.add(new CardDefinition("hp-energy","HP供能夹具",CardCategory.ENERGY,TrainerCategory.NONE,"H",Set.of("international"),false,false,60,Map.of(),EffectSupport.SUPPORTED,null));var database=new CardDatabase(cards);var a=new ArrayList<>(StarterDeck100PokemonTest.deck(A,113));var b=new ArrayList<>(StarterDeck100PokemonTest.deck(B,1));b.set(0,StarterDeck100CombatTest.card(B,"hp-energy"));check(HitPointEnergyDependencies.unsupportedReason(combat,b).isEmpty(),"HP-dependent Energy alone wrongly rejected");TopDeckLookTest.rejects(()->new ServerMatch(A,B,a,b,StarterDeck100CombatTest.RULE,database,combat,new ServerRandom(0)));a.set(0,StarterDeck100CombatTest.card(A,"hp-energy"));check(new DeckValidator(database,combat).validate(StarterDeck100CombatTest.RULE,a).issues().stream().anyMatch(i->i.code().equals("循环供能依赖未支持")),"deck UI did not report unsupported cycle before setup");}
}
